-- Bronze tables: raw copies of the RIK open-data CSV files.
-- GENERATED by `python scripts/bronze_schema.py` (single source of truth for header -> column mapping).
-- Do not edit by hand; tests/test_bronze_unit.py fails if this file and bronze_schema.py drift apart.
--
-- * Every source column is String, stored exactly as in the file (no casting; '' stays '').
-- * _source_file / _file_version are filled by the loader, _loaded_at defaults to now().
-- * ReplacingMergeTree(_loaded_at): rows sharing the ORDER BY key collapse to the newest load.
--   Read with FINAL (or argMax(..., _loaded_at)) to get one row per key.
-- * scripts/load_bronze.py additionally replaces the whole partition per file, so reloads are
--   idempotent even before background merges. See docs/bronze_tables.md.

-- Source: 1.aruannete_yldandmed_kuni_<version>.csv
-- Grain:  one row per annual report (report_id)
CREATE TABLE IF NOT EXISTS bronze.rik_report_general
(
    `report_id` String COMMENT 'report_id',
    `taidetud_aruanne_report_id` String COMMENT 'taidetud_aruanne_report_id',
    `registrikood` String COMMENT 'registrikood',
    `oiguslik_vorm` String COMMENT 'õiguslik vorm',
    `staatus` String COMMENT 'staatus',
    `aruandeaasta` String COMMENT 'aruandeaasta',
    `kas_konsolideeritud` String COMMENT 'kas konsolideeritud?',
    `period_start` String COMMENT 'period_start',
    `period_end` String COMMENT 'period_end',
    `esitatud_kpv` String COMMENT 'esitatud_kpv',
    `kas_auditeeritud` String COMMENT 'kas auditeeritud?',
    `valitud_aruanne_kategooria` String COMMENT 'valitud aruanne kategooria',
    `minimaalne_kategooria_andmete_alusel` String COMMENT 'minimaalne kategooria andmete alusel',
    `auditi_toovotu_liik` String COMMENT 'auditi töövõtu liik',
    `audiitori_otsuse_tyyp` String COMMENT 'audiitori otsuse tüüp',
    `modifikatsioon_asjaolu_rohutamine` String COMMENT 'modifikatsioon asjaolu rõhutamine',
    `modifikatsioon_muu_asjaolu` String COMMENT 'modifikatsioon muu asjaolu',
    `modifikatsioon_tegevuse_jatkuvus` String COMMENT 'modifikatsioon tegevuse jatkuvus',
    `audiitorettevotja_aev` String COMMENT 'Audiitorettevõtja (AEV)',
    `_source_file` String,
    `_file_version` String,
    `_loaded_at` DateTime DEFAULT now()
)
ENGINE = ReplacingMergeTree(_loaded_at)
ORDER BY (report_id);

-- Source: 4.<year>_aruannete_elemendid_kuni_<version>.csv (one file per report year)
-- Grain:  one row per report x tabel x element (long format)
CREATE TABLE IF NOT EXISTS bronze.rik_report_elements
(
    `report_id` String COMMENT 'report_id',
    `tabel` String COMMENT 'tabel',
    `elemendi_label` String COMMENT 'elemendi_label',
    `elemendi_nimetus` String COMMENT 'elemendi_nimetus',
    `vaartus` String COMMENT 'vaartus',
    `report_year` UInt16 COMMENT 'from the file name',
    `_source_file` String,
    `_file_version` String,
    `_loaded_at` DateTime DEFAULT now()
)
ENGINE = ReplacingMergeTree(_loaded_at)
PARTITION BY report_year
ORDER BY (report_id, tabel, elemendi_nimetus, elemendi_label);

-- Source: 2.EMTAK_myygitulu_kuni_<version>.csv
-- Grain:  one row per report x EMTAK code x EMTAK version
CREATE TABLE IF NOT EXISTS bronze.rik_report_emtak_revenue
(
    `report_id` String COMMENT 'report_id',
    `emtak` String COMMENT 'emtak',
    `jaotatud_myygitulu` String COMMENT 'Jaotatud müügitulu',
    `pohitegevusala` String COMMENT 'põhitegevusala',
    `emtak_version` String COMMENT 'emtak_version',
    `_source_file` String,
    `_file_version` String,
    `_loaded_at` DateTime DEFAULT now()
)
ENGINE = ReplacingMergeTree(_loaded_at)
ORDER BY (report_id, emtak, emtak_version);

-- Source: avaandmed/ettevotja_rekvisiidid__lihtandmed.csv (updated daily, current state only)
-- Grain:  one row per company (ariregistri_kood), current state
CREATE TABLE IF NOT EXISTS bronze.rik_company_basic
(
    `nimi` String COMMENT 'nimi',
    `ariregistri_kood` String COMMENT 'ariregistri_kood',
    `ettevotja_oiguslik_vorm` String COMMENT 'ettevotja_oiguslik_vorm',
    `ettevotja_oigusliku_vormi_alaliik` String COMMENT 'ettevotja_oigusliku_vormi_alaliik',
    `kmkr_nr` String COMMENT 'kmkr_nr',
    `ettevotja_staatus` String COMMENT 'ettevotja_staatus',
    `ettevotja_staatus_tekstina` String COMMENT 'ettevotja_staatus_tekstina',
    `ettevotja_esmakande_kpv` String COMMENT 'ettevotja_esmakande_kpv',
    `ettevotja_aadress` String COMMENT 'ettevotja_aadress',
    `asukoht_ettevotja_aadressis` String COMMENT 'asukoht_ettevotja_aadressis',
    `asukoha_ehak_kood` String COMMENT 'asukoha_ehak_kood',
    `asukoha_ehak_tekstina` String COMMENT 'asukoha_ehak_tekstina',
    `indeks_ettevotja_aadressis` String COMMENT 'indeks_ettevotja_aadressis',
    `ads_adr_id` String COMMENT 'ads_adr_id',
    `ads_ads_oid` String COMMENT 'ads_ads_oid',
    `ads_normaliseeritud_taisaadress` String COMMENT 'ads_normaliseeritud_taisaadress',
    `teabesysteemi_link` String COMMENT 'teabesysteemi_link',
    `_source_file` String,
    `_file_version` String,
    `_loaded_at` DateTime DEFAULT now()
)
ENGINE = ReplacingMergeTree(_loaded_at)
ORDER BY (ariregistri_kood);
